-- match by nearest x/z (not by order, in case parts were added/removed)
local function restore(root, name, rows)
	local done = 0
	for _, b in ipairs(root:GetDescendants()) do
		if b:IsA("BasePart") and b.Name == name then
			local best, bd
			for _, r in ipairs(rows) do
				local d = (b.Position.X - r[1]) ^ 2 + (b.Position.Z - r[2]) ^ 2
				if not bd or d < bd then best, bd = r, d end
			end
			if best and bd < 0.01 then
				local rot = b.CFrame - b.Position
				b.Size = Vector3.new(b.Size.X, best[3], b.Size.Z)
				b.CFrame = CFrame.new(b.Position.X, best[4], b.Position.Z) * rot
				done += 1
			end
		end
	end
	print("restored " .. done .. " " .. name)
end
restore(workspace.LayoutDecor.LakeSurround, "Blocker", data.lake)
-- Bridge RailBlockers are TILTED along the arch, so they were shrunk along their own up axis (bottom face kept).
-- Undo = grow each back to 12 along its own up axis (the rows above are the old world centres, for reference only).
local n = 0
for _, b in ipairs(workspace.LayoutDecor.StreamDecor.Bridges:GetDescendants()) do
	if b:IsA("BasePart") and b.Name == "RailBlocker" and b.Size.Y < 12 then
		b.CFrame = b.CFrame * CFrame.new(0, (12 - b.Size.Y) / 2, 0)
		b.Size = Vector3.new(b.Size.X, 12, b.Size.Z)
		n += 1
	end
end
print("restored " .. n .. " RailBlocker")
